tasks.setup:
// memory data the LOAD instructions read
const data = { 200: 7, 201: 3 };
// the program: address -> instruction (each instruction is 4 bytes)
const program = {
  100: { op: 'LOAD', dst: 'R0', addr: 200 },
  104: { op: 'LOAD', dst: 'R1', addr: 201 },
  108: { op: 'ADD',  dst: 'R2', a: 'R0', b: 'R1' },
};
const reg = { R0: 0, R1: 0, R2: 0 };
let pc = 100;

tasks.code:
// run the cycle until pc leaves the program (reaches 112)
while (program[pc]) {
  // FETCH: read the instruction at the address in pc
  const instr = program[pc];
  // DECODE + EXECUTE: act on the opcode
  if (instr.op === 'LOAD') {
    reg[instr.dst] = data[instr.addr];
  } else if (instr.op === 'ADD') {
    reg[instr.dst] = reg[instr.a] + reg[instr.b];
  }
  // ADVANCE pc: no JUMP here, so add the 4-byte instruction size
  pc = pc + 4;
}
console.log(`R0=${reg.R0} R1=${reg.R1} R2=${reg.R2}`);
